/* ---------- widget ---------- */
function onTheory(root){const w=root.querySelector('#w-mix');if(!w)return;
  w.innerHTML=`<label>Горячая: m₁ = <output id="wm1">2</output> кг<input type="range" id="wM1" min="0.5" max="5" step="0.5" value="2"></label>
<label>t₁ = <output id="wt1">80</output> °С<input type="range" id="wT1" min="40" max="100" step="5" value="80"></label>
<label>Холодная: m₂ = <output id="wm2">3</output> кг<input type="range" id="wM2" min="0.5" max="5" step="0.5" value="3"></label>
<label>t₂ = <output id="wt2">20</output> °С<input type="range" id="wT2" min="0" max="35" step="5" value="20"></label>
<div id="wmS" style="display:flex;justify-content:center"></div><div id="wmO" class="small" style="text-align:center;margin-top:6px"></div>`;
  const g=id=>w.querySelector(id);
  const draw=()=>{const m1=+g('#wM1').value,t1=+g('#wT1').value,m2=+g('#wM2').value,t2=+g('#wT2').value;
    g('#wm1').textContent=N(m1);g('#wt1').textContent=t1;g('#wm2').textContent=N(m2);g('#wt2').textContent=t2;
    const th=(m1*t1+m2*t2)/(m1+m2);const q=4200*m1*(t1-th)/1000;
    g('#wmS').innerHTML=mixPic({m:m1,t:t1,top:N(t1)+' °С',bot:N(m1)+' кг'},{m:m2,t:t2,top:N(t2)+' °С',bot:N(m2)+' кг'},{t:th,top:'θ ≈ '+N(rd(th,1))+' °С',bot:N(m1+m2)+' кг'});
    g('#wmO').innerHTML=`θ = (${N(m1)}·${t1} + ${N(m2)}·${t2}) / ${N(m1+m2)} ≈ <span class="out">${N(rd(th,1))} °С</span>. Горячая вода отдала ≈ <span class="out">${N(rd(q,1))} кДж</span> — ровно столько получила холодная.`;};
  w.querySelectorAll('input').forEach(i=>i.oninput=draw);draw();}

